function assertReadableUrl(raw) {
  const value = String(raw || "").trim();
  if (!value) throw new Error("INVALID_URL: informe a URL.");
  const schemeMatch = /^([a-z][a-z0-9+.-]*):/i.exec(value);
  if (schemeMatch) {
    const scheme = schemeMatch[1].toLowerCase();
    if (scheme !== "http" && scheme !== "https") {
      throw new Error(`URL_BLOCKED: esquema '${scheme}:' n\xE3o permitido (use http ou https).`);
    }
  }
  let parsed;
  try {
    parsed = new URL(schemeMatch ? value : `https://${value}`);
  } catch {
    throw new Error("INVALID_URL: URL inv\xE1lida.");
  }
  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    throw new Error(`URL_BLOCKED: esquema '${parsed.protocol}' n\xE3o permitido.`);
  }
  const host = parsed.hostname.toLowerCase();
  const isLocalHost = host === "localhost" || host === "127.0.0.1" || host === "::1" || host.endsWith(".localhost") || /^10\./.test(host) || /^192\.168\./.test(host) || /^172\.(1[6-9]|2\d|3[01])\./.test(host) || /^169\.254\./.test(host);
  if (isLocalHost) throw new Error("URL_BLOCKED: endere\xE7os locais/privados n\xE3o s\xE3o acess\xEDveis.");
  return parsed.toString();
}
async function readPageText(url, options = {}) {
  const timeoutMs = Math.max(3e3, Math.min(3e4, options.timeoutMs ?? 2e4));
  const maxChars = Math.max(200, Math.min(2e4, options.maxChars ?? 6e3));
  let safeUrl;
  try {
    safeUrl = assertReadableUrl(url);
  } catch (err) {
    return { ok: false, error: err?.message || "URL inv\xE1lida." };
  }
  let browser = null;
  try {
    const pw = await import("playwright");
    browser = await pw.chromium.launch({ headless: true, args: ["--no-sandbox", "--disable-dev-shm-usage"] });
    const page = await browser.newPage({ userAgent: "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36" });
    await page.goto(safeUrl, { waitUntil: "domcontentloaded", timeout: timeoutMs });
    await page.waitForTimeout(1200);
    const title = await page.title();
    const bodyText = await page.evaluate(() => {
      const remove = ["script", "style", "noscript", "svg"];
      for (const tag of remove) document.querySelectorAll(tag).forEach((el) => el.remove());
      return (document.body.innerText || "").replace(/\n{3,}/g, "\n\n");
    });
    const text = String(bodyText || "").slice(0, maxChars).trim();
    const finalUrl = page.url();
    await browser.close();
    browser = null;
    if (!text) {
      return { ok: false, url: finalUrl, title, error: "PAGE_EMPTY: a p\xE1gina n\xE3o retornou texto leg\xEDvel (pode exigir JavaScript/login)." };
    }
    const blockedSignal = /unusual traffic|not a robot|captcha|tráfego incomum|access denied|403 forbidden|if this persists|anonymized error|enable javascript|verify you are human/i.test(text);
    const wordCount = text.split(/\s+/).filter((w) => /[A-Za-zÀ-ÿ]{3,}/.test(w)).length;
    const looksLikeErrorPage = wordCount < 25;
    if (blockedSignal || looksLikeErrorPage) {
      return {
        ok: false,
        url: finalUrl,
        title,
        error: blockedSignal ? "PAGE_BLOCKED_BY_SITE: o site exigiu verifica\xE7\xE3o humana (CAPTCHA/anti-bot). N\xE3o \xE9 poss\xEDvel ler este conte\xFAdo automaticamente \u2014 use outra fonte ou pe\xE7a ao Mestre para abrir no navegador." : "PAGE_WITHOUT_CONTENT: a p\xE1gina n\xE3o exp\xF4s conte\xFAdo leg\xEDvel (possivelmente bloqueada por anti-bot ou carregada por JavaScript pesado)."
      };
    }
    return { ok: true, url: finalUrl, title, text };
  } catch (err) {
    try {
      await browser?.close();
    } catch {
    }
    const message = String(err?.message || err);
    if (/Cannot find module|Executable doesn't exist/i.test(message)) {
      return { ok: false, error: 'BROWSER_INSTALL_REQUIRED: execute "npx playwright install chromium" para habilitar a leitura de p\xE1ginas.' };
    }
    return { ok: false, error: `PAGE_READ_FAILED: ${message.slice(0, 300)}` };
  }
}
