var nativeKillProcessTool = {
  name: "kill_process",
  description: "Encerra um processo em execu\xE7\xE3o pelo seu PID. Opera\xE7\xE3o R2 protegida por consentimento. PIDs e processos do sistema s\xE3o protegidos.",
  category: "system",
  riskLevel: "R2",
  isSimulated: false,
  parameters: {
    type: "object",
    properties: {
      pid: {
        type: "number",
        description: "PID (Identificador de Processo) a ser encerrado."
      },
      processName: {
        type: "string",
        description: "Nome do processo para dupla confirma\xE7\xE3o (opcional)."
      }
    },
    required: ["pid"],
    additionalProperties: false
  },
  outputSchema: {
    type: "object",
    requiredFields: ["success", "pid", "simulated"]
  },
  execute: async ({ pid, processName }) => {
    if (typeof pid !== "number" || pid < 10) {
      throw new Error("SYSTEM_PID_PROTECTED: PIDs do sistema (< 10) n\xE3o podem ser encerrados.");
    }
    const blockedNames = [
      "system",
      "smss",
      "csrss",
      "wininit",
      "winlogon",
      "lsass",
      "services",
      "svchost",
      "dwm",
      "explorer",
      "init",
      "systemd",
      "kernel",
      "node",
      "liora"
    ];
    if (processName) {
      const lower = processName.toLowerCase();
      if (blockedNames.some((b) => lower.includes(b))) {
        throw new Error(`SYSTEM_PROCESS_PROTECTED: O processo '${processName}' \xE9 protegido e n\xE3o pode ser encerrado.`);
      }
    }
    if (os5.platform() === "win32") {
      const { exitCode, stderr } = await execRealCommand(`taskkill /F /PID ${pid}`, 5e3);
      if (exitCode !== 0) {
        throw new Error(`PROCESS_TERMINATION_FAILED: Falha ao encerrar PID ${pid}: ${stderr.trim() || "Processo n\xE3o encontrado ou acesso negado."}`);
      }
      return { success: true, pid, message: `Processo PID ${pid} encerrado com sucesso.`, simulated: false };
    } else {
      const { exitCode, stderr } = await execRealCommand(`kill -9 ${pid}`, 5e3);
      if (exitCode !== 0) {
        throw new Error(`PROCESS_TERMINATION_FAILED: Falha ao encerrar PID ${pid}: ${stderr.trim() || "Acesso negado."}`);
      }
      return { success: true, pid, message: `Processo PID ${pid} encerrado com sucesso.`, simulated: false };
    }
  }
};
var nativeWorkspaceSearchFilesTool = {
  name: "workspace_search_files",
  description: "Busca arquivos e pastas no workspace seguro da LIORA (~/.liora/workspace) por nome ou extens\xE3o. Risco R0.",
  category: "workspace",
  riskLevel: "R0",
  isSimulated: false,
  parameters: {
    type: "object",
    properties: {
      query: {
        type: "string",
        description: 'Termo de busca ou extens\xE3o (ex: ".md", "relatorio", "dados"). Vazio lista todos.'
      },
      maxResults: {
        type: "number",
        description: "N\xFAmero m\xE1ximo de resultados (padr\xE3o: 50, m\xE1x: 200).",
        default: 50
      }
    },
    additionalProperties: false
  },
  outputSchema: {
    type: "object",
    requiredFields: ["files", "totalMatches", "workspaceRoot", "simulated"]
  },
  execute: async ({ query, maxResults }) => {
    const root = ensureWorkspaceRoot();
    const limit = Math.min(200, Math.max(1, maxResults || 50));
    const term = (query || "").toLowerCase().trim();
    const results = [];
    function walk(dir, depth = 0) {
      if (depth > 6 || results.length >= limit) return;
      let entries = [];
      try {
        entries = fs6.readdirSync(dir, { withFileTypes: true });
      } catch {
        return;
      }
      for (const entry of entries) {
        if (results.length >= limit) break;
        const full = path7.join(dir, entry.name);
        const rel = path7.relative(root, full).replace(/\\/g, "/");
        if (full !== root && !full.startsWith(root + path7.sep)) continue;
        const matches = !term || entry.name.toLowerCase().includes(term);
        if (matches) {
          try {
            const stat = fs6.statSync(full);
            results.push({
              path: rel,
              sizeBytes: stat.size,
              modifiedAt: stat.mtime.toISOString(),
              isDirectory: entry.isDirectory()
            });
          } catch {
          }
        }
        if (entry.isDirectory()) {
          walk(full, depth + 1);
        }
      }
    }
    walk(root);
    return {
      files: results,
      totalMatches: results.length,
      workspaceRoot: root,
      simulated: false
    };
  }
};
var nativeWorkspaceDeleteFileTool = {
  name: "workspace_delete_file",
  description: "Exclui permanentemente um arquivo no workspace seguro da LIORA. Risco R2 \u2014 requer consentimento expl\xEDcito.",
  category: "workspace",
  riskLevel: "R2",
  isSimulated: false,
  parameters: {
    type: "object",
    properties: {
      filePath: {
        type: "string",
        description: 'Caminho relativo do arquivo no workspace (ex: "temp/resultado.txt").'
      }
    },
    required: ["filePath"],
    additionalProperties: false
  },
  outputSchema: {
    type: "object",
    requiredFields: ["success", "filePath", "simulated"]
  },
  execute: async ({ filePath }) => {
    const safePath = resolveSafeWorkspacePath(filePath);
    const root = ensureWorkspaceRoot();
    if (path7.resolve(safePath) === path7.resolve(root)) {
      throw new Error("WORKSPACE_ROOT_PROTECTED: N\xE3o \xE9 permitido excluir a raiz do workspace.");
    }
    if (!fs6.existsSync(safePath)) {
      throw new Error(`FILE_NOT_FOUND: O arquivo '${filePath}' n\xE3o existe no workspace.`);
    }
    const stat = fs6.statSync(safePath);
    if (stat.isDirectory()) {
      fs6.rmSync(safePath, { recursive: true, force: true });
    } else {
      fs6.unlinkSync(safePath);
    }
    return {
      success: true,
      filePath: filePath.trim().replace(/^[./\\]+/, ""),
      simulated: false
    };
  }
};
var nativeWorkspaceMoveFileTool = {
  name: "workspace_move_file",
  description: "Move ou renomeia um arquivo dentro do workspace seguro da LIORA. Risco R1.",
  category: "workspace",
  riskLevel: "R1",
  isSimulated: false,
  parameters: {
    type: "object",
    properties: {
      sourcePath: {
        type: "string",
        description: "Caminho relativo de origem dentro do workspace."
      },
      destPath: {
        type: "string",
        description: "Caminho relativo de destino dentro do workspace."
      },
      overwrite: {
        type: "boolean",
        description: "Sobrescrever se o arquivo de destino j\xE1 existir (padr\xE3o: false).",
        default: false
      }
    },
    required: ["sourcePath", "destPath"],
    additionalProperties: false
  },
  outputSchema: {
    type: "object",
    requiredFields: ["success", "sourcePath", "destPath", "simulated"]
  },
  execute: async ({ sourcePath, destPath, overwrite }) => {
    const safeSrc = resolveSafeWorkspacePath(sourcePath);
    const safeDest = resolveSafeWorkspacePath(destPath);
    if (!fs6.existsSync(safeSrc)) {
      throw new Error(`FILE_NOT_FOUND: Arquivo de origem '${sourcePath}' n\xE3o encontrado.`);
    }
    if (fs6.existsSync(safeDest) && !overwrite) {
      throw new Error(`DESTINATION_EXISTS: Destino '${destPath}' j\xE1 existe. Use overwrite: true para substituir.`);
    }
    const destDir = path7.dirname(safeDest);
    if (!fs6.existsSync(destDir)) {
      fs6.mkdirSync(destDir, { recursive: true });
    }
    fs6.renameSync(safeSrc, safeDest);
    return {
      success: true,
      sourcePath: sourcePath.trim().replace(/^[./\\]+/, ""),
      destPath: destPath.trim().replace(/^[./\\]+/, ""),
      simulated: false
    };
  }
};
